const salesPath = path.resolve('sales.csv');
const pricingPath = path.resolve('pricing-sources.md');
const summaryPath = path.resolve('monthly_summary.csv');
const reportPath = path.resolve('report.md');

function buildMonthlySummary(rows) {
  const validRows = rows.filter((r) => r.validDate && r.validAmount);
  const invalidRows = rows.filter((r) => !r.validDate || !r.validAmount);
  const totals = new Map();
  for (const r of validRows) {
    const month = r.dateText.slice(0, 7);
    totals.set(month, (totals.get(month) ?? 0) + r.amount);
  }
  const months = [...totals.keys()].sort();
  const summary = months.map((month, idx) => {
    const total = round2(totals.get(month));
    const prev = idx > 0 ? round2(totals.get(months[idx - 1])) : null;
    const mom = prev === null || prev === 0 ? null : (total - prev) / prev;

const salesText = fs.readFileSync(salesPath, 'utf8');
const pricingText = fs.readFileSync(pricingPath, 'utf8');
const rows = parseCsv(salesText);
const { summary, validRows, invalidRows } = buildMonthlySummary(rows);
const pricing = parsePricing(pricingText);
writeSummary(summary);
writeReport({ summary, rows, validRows, invalidRows, pricing });
verify(summary, pricing);

